\label{lem:path-rademacher}
For any deterministic sample $x_1,\ldots,x_n\in\mathbb R^d$,
\[
    \widehat{\mathfrak R}_n(\mathcal F_{B,m})
    \leq
    {2B\over n}
    \left(\sum_{i=1}^n\|x_i\|_2^2\right)^{1/2}.
\]
For the multi-index distribution above, let
$\widehat f_{\mathrm{MLP}}^{(r_0)}$ be an empirical squared-loss minimizer
over $\mathcal F_{B,m}$. There is a universal constant $C<\infty$ such that
\begin{align*}
    \mathbb E\left[
        \|\widehat f_{\mathrm{MLP}}^{(r_0)}-f_{r_0}^\star
        \|_{L^2(P_x)}^2
    \right]
    &\leq
    \inf_{f\in\mathcal F_{B,m}}
    \|f-f_{r_0}^\star\|_{L^2(P_x)}^2\\
    &\quad+
    CB^2\sqrt{
        {(Kr_0+R^2)(Kr_0+R^2+\log(en))\over n}
    }\\
    &\quad+
    CBG_0\sqrt{{Kr_0+R^2\over n}}.
\end{align*}

\begin{align*}
    \mathbb E\left[
        \|\widehat f_{\mathrm{MLP}}^{(r_0)}-f_{r_0}^\star
        \|_{L^2(P_x)}^2
    \right]
    &\leq
    \inf_{f\in\mathcal F_{B,m}}
    \|f-f_{r_0}^\star\|_{L^2(P_x)}^2\\
    &\quad+
    CB^2\sqrt{
        {(Kr_0+R^2)(Kr_0+R^2+\log(en))\over n}
    }\\
    &\quad+
    CBG_0\sqrt{{Kr_0+R^2\over n}}.
\end{align*}

\begin{align*}
    \mathbb E\left[
        \|\widehat f_{\mathrm{MLP}}^{(r_0)}-f_{r_0}^\star
        \|_{L^2(P_x)}^2
    \right]
    &\leq
    \inf_{f\in\mathcal F_{B,m}}
    \|f-f_{r_0}^\star\|_{L^2(P_x)}^2\\
    &\quad+
    C\,\mathbb E\left[
        {B(BM_n+G_0)\over n}
        \left(\sum_{i=1}^n\|x_i\|_2^2\right)^{1/2}
    \right].
\end{align*}

\begin{align*}
    \mathbb E\left[
        \|\widehat f_{\mathrm{MLP}}^{(r_0)}-f_{r_0}^\star
        \|_{L^2(P_x)}^2
    \right]
    &\leq
    \|F_K-f_{r_0}^\star\|_{L^2(P_x)}^2\\
    &\quad+
    CB_K^2\sqrt{
        {(Kr_0+R^2)(Kr_0+R^2+\log(en_K))\over n_K}
    }\\
    &\quad+
    CB_KG_0\sqrt{{Kr_0+R^2\over n_K}}.
\end{align*}
